// lifo4_fcov -- functional coverage model for lifo4
// Built from: traceability_matrix.md (plan-audit, approved),
//             sha256:88efd915d0a74163dbd4d49f5d8775e5241b0655723c4df2df0e7a793dc49313
//
// CLOSURE STATEMENT
// Sampling: every rising edge of clk, using port values just before the edge.
// Crosses and occupancy bins are sampled only when rst_n is high.
// Occupancy is taken from count before the edge:
//   0 = empty, 1..3 = neither empty nor full (mid), 4 = full.
//
// Planned bins (15):
//   0  CROSS_PUSH_EMPTY  push alone, stack empty               (LIFO-PUSH)
//   1  CROSS_PUSH_MID    push alone, neither empty nor full    (LIFO-PUSH)
//   2  CROSS_PUSH_FULL   push alone, stack full                (LIFO-OVERFLOW)
//   3  CROSS_POP_EMPTY   pop alone, stack empty                (LIFO-UNDERFLOW)
//   4  CROSS_POP_MID     pop alone, neither empty nor full     (LIFO-POP)
//   5  CROSS_POP_FULL    pop alone, stack full                 (LIFO-POP)
//   6  CROSS_BOTH_EMPTY  push and pop, stack empty             (LIFO-BOTH-EMPTY)
//   7  CROSS_BOTH_MID    push and pop, neither empty nor full  (LIFO-REPLACE)
//   8  CROSS_BOTH_FULL   push and pop, stack full              (LIFO-REPLACE)
//   9  OCC_0             occupancy 0                           (all)
//   10 OCC_1             occupancy 1                           (all)
//   11 OCC_2             occupancy 2                           (all)
//   12 OCC_3             occupancy 3                           (all)
//   13 OCC_4             occupancy 4                           (all)
//   14 RESET_NONEMPTY    reset applied while stack holds a word (LIFO-RESET)
//
// Exclusions: none. The matrix waives no scenario and names none as unreachable.
// planned = 15. holes = number of planned bins not yet hit.

module lifo4_fcov (
    input  logic       clk, rst_n, push, pop,
    input  logic [7:0] din, dout,
    input  logic [2:0] count,
    input  logic       empty, full, err,
    output int         planned,   // how many bins the model plans
    output int         holes      // how many of them have not been hit yet
);

    localparam int NB = 15;

    localparam int B_PUSH_EMPTY = 0;
    localparam int B_PUSH_MID   = 1;
    localparam int B_PUSH_FULL  = 2;
    localparam int B_POP_EMPTY  = 3;
    localparam int B_POP_MID    = 4;
    localparam int B_POP_FULL   = 5;
    localparam int B_BOTH_EMPTY = 6;
    localparam int B_BOTH_MID   = 7;
    localparam int B_BOTH_FULL  = 8;
    localparam int B_OCC0       = 9;
    localparam int B_RESET      = 14;

    logic [NB-1:0] hit;

    initial hit = '0;

    always @(posedge clk) begin
        if (rst_n === 1'b1) begin
            // Occupancy bins
            if (count == 3'd0) hit[B_OCC0 + 0] <= 1'b1;
            if (count == 3'd1) hit[B_OCC0 + 1] <= 1'b1;
            if (count == 3'd2) hit[B_OCC0 + 2] <= 1'b1;
            if (count == 3'd3) hit[B_OCC0 + 3] <= 1'b1;
            if (count == 3'd4) hit[B_OCC0 + 4] <= 1'b1;

            // Operation x occupancy crosses
            if (push === 1'b1 && pop === 1'b0) begin
                if (count == 3'd0)                      hit[B_PUSH_EMPTY] <= 1'b1;
                if (count >= 3'd1 && count <= 3'd3)     hit[B_PUSH_MID]   <= 1'b1;
                if (count == 3'd4)                      hit[B_PUSH_FULL]  <= 1'b1;
            end
            if (push === 1'b0 && pop === 1'b1) begin
                if (count == 3'd0)                      hit[B_POP_EMPTY]  <= 1'b1;
                if (count >= 3'd1 && count <= 3'd3)     hit[B_POP_MID]    <= 1'b1;
                if (count == 3'd4)                      hit[B_POP_FULL]   <= 1'b1;
            end
            if (push === 1'b1 && pop === 1'b1) begin
                if (count == 3'd0)                      hit[B_BOTH_EMPTY] <= 1'b1;
                if (count >= 3'd1 && count <= 3'd3)     hit[B_BOTH_MID]   <= 1'b1;
                if (count == 3'd4)                      hit[B_BOTH_FULL]  <= 1'b1;
            end
        end else if (rst_n === 1'b0) begin
            // Reset applied while the stack holds a word
            if (count >= 3'd1 && count <= 3'd4)         hit[B_RESET]      <= 1'b1;
        end
    end

    assign planned = NB;
    assign holes   = NB - $countones(hit);

endmodule
